# GENERATED by sparring/gen.py: preset "button_spam". Edit puppet_core.py or gen.py, not this file.
"""
Parametric sparring bot ("puppet"). The preset bots in sparring/bots/ are this
file with a different PARAMS dict prepended (see sparring/gen.py). PARAMS may
also be a LIST of dicts plus PERIOD: the bot then cycles through the profiles
every PERIOD hands (the "switcher").

Preflop strength is a percentile (0 = AA, 1 = worst) from a Chen-style score.
Postflop strength is a rough 0..1 score from the made hand and simple draws.
Everything is deliberately crude: the point is a *consistent, tunable* style,
not a good player.
"""

import random

import eval7

DEFAULTS = {
    # preflop
    "vpip": 0.60,          # share of hands played (top X%)
    "pfr": 0.40,           # share of hands raised (top X%)
    "threebet": 0.12,      # share re-raised when facing a raise (top X%)
    "call_raise": 0.30,    # share called when facing a raise (top X%), if not re-raising
    "open_bb": 2.5,        # open size, in big blinds (total)
    "threebet_mult": 3.0,  # re-raise to this multiple of their bet
    "limp": False,         # play hands in vpip-but-not-pfr range by limping (else fold them)
    "pf_bluff": 0.0,       # chance to raise a hand outside pfr range
    "nash": False,         # at <=15bb use an approximate heads-up Nash push/fold chart
    "shove_bb": 0.0,       # at or below this many effective bb: push/fold
    "shove_pct": 0.35,     # ...shove top X% of hands
    "call_shove_pct": 0.30,  # ...and call an all-in with top X%
    # postflop
    "cbet": 0.6,           # chance to bet when checked to (with a hand worth betting)
    "bluff": 0.15,         # chance to bet when checked to with air
    "value_min": 0.60,     # strength at which we bet for value
    "bet_frac": (0.5, 0.75),     # bet sizes, fraction of pot (random choice)
    "size_tell": "none",   # "inverted": big bets with air, small with strong; "polar": 2.5x pot or nothing
    "trap": 0.0,           # with a monster and checked to: check (to raise later) this often
    "call_min": 0.40,      # facing a bet: call at this strength...
    "size_sens": 0.30,     # ...plus this per pot-sized bet (bigger bets need more)
    "raise_min": 0.80,     # raise a bet with this strength
    "raise_mult": 3.0,     # raise to this multiple of their bet
    "bluff_raise": 0.0,    # raise a bet with air this often
    "float": 0.0,          # call a flop bet with air this often (then bet turn if checked to)
    "min_raise_only": False,  # every raise is a min-raise
    "raise_classes": (),   # hand classes (e.g. '72o') always raised preflop
    "always_fold": False,
    "always_shove": False,
    "station": False,      # never fold, never raise
}

PARAMS = {'pfr': 1.0, 'vpip': 1.0, 'open_bb': 2.2, 'threebet': 0.04, 'call_raise': 0.0, 'cbet': 0.7, 'bluff': 0.4}
PERIOD = 25

RANKS = "23456789TJQKA"
_PCT = {}


def _chen(hi, lo, suited):
    pts = {"A": 10, "K": 8, "Q": 7, "J": 6, "T": 5}
    h = pts.get(hi, (RANKS.index(hi) + 2) / 2)
    if hi == lo:
        return max(5, h * 2)
    s = h + (2 if suited else 0)
    gap = RANKS.index(hi) - RANKS.index(lo) - 1
    s -= {0: 0, 1: 1, 2: 2, 3: 4}.get(gap, 5)
    if gap <= 1 and RANKS.index(hi) < RANKS.index("Q"):
        s += 1
    return s


def _build():
    scores = []
    for i, a in enumerate(RANKS):
        for j, b in enumerate(RANKS):
            if j > i:
                continue
            if i == j:
                scores.append((_chen(a, b, False), a + b, 6))
            else:
                scores.append((_chen(a, b, True), a + b + "s", 4))
                scores.append((_chen(a, b, False), a + b + "o", 12))
    scores.sort(key=lambda x: -x[0])
    run = 0
    for _, cls, n in scores:
        run += n
        _PCT[cls] = run / 1326


_build()


def cls_of(cards):
    a, b = sorted(cards, key=lambda c: -RANKS.index(c[0]))
    if a[0] == b[0]:
        return a[0] + b[0]
    return a[0] + b[0] + ("s" if a[1] == b[1] else "o")


def post_strength(hole, board):
    """Rough 0..1 strength of our hand on this board."""
    cards = [eval7.Card(c) for c in hole + board]
    kind = eval7.evaluate(cards) >> 24          # 0 high card, 1 pair, 2 two pair, 3 trips, ...
    hr = [RANKS.index(c[0]) for c in hole]
    br = [RANKS.index(c[0]) for c in board]
    if kind >= 3:
        return 0.88 + 0.02 * min(kind - 3, 5)
    if kind == 2:
        used = sum(1 for r in hr if r in br)
        return 0.82 if used == 2 else 0.60 if used == 1 else 0.3
    if kind == 1:
        pr = [r for r in hr if r in br]
        if pr:
            return 0.66 if pr[0] == max(br) else 0.52 if pr[0] >= sorted(br)[len(br) // 2] else 0.42
        if hr[0] == hr[1]:                       # pocket pair
            return 0.62 if hr[0] > max(br) else 0.45
        return 0.12
    s = 0.15 + 0.01 * max(hr)
    if len(board) < 5:
        suits = [c[1] for c in hole + board]
        if any(suits.count(x) >= 4 for x in "shdc"):
            s = max(s, 0.50)
        ranks = {RANKS.index(c[0]) for c in hole + board}
        if any(all(r + k in ranks for k in range(4)) for r in range(10)):
            s = max(s, 0.48)
    return s


# Approximate heads-up Nash shove (button) / call (big blind) frequencies by
# effective stack in big blinds. Rough values from published push/fold charts.
NASH_PUSH = ((2, 1.0), (4, 0.95), (6, 0.78), (8, 0.66), (10, 0.58), (12, 0.50), (15, 0.42))
NASH_CALL = ((2, 0.90), (4, 0.62), (6, 0.52), (8, 0.44), (10, 0.38), (12, 0.34), (15, 0.30))


def interp(table, x):
    if x <= table[0][0]:
        return table[0][1]
    for (x0, y0), (x1, y1) in zip(table, table[1:]):
        if x <= x1:
            return y0 + (y1 - y0) * (x - x0) / (x1 - x0)
    return table[-1][1]


def facing_raise_pf(state):
    return state["current_bet"] > state["blinds"]["bb"]


def prm(state):
    p = PARAMS
    if isinstance(p, list):
        p = p[(state.get("hand_num", 0) // PERIOD) % len(p)]
    return {**DEFAULTS, **p}


def opp_of(state):
    return next(x for x in state["players"] if x["bot_id"] != state["your_bot_id"])


def raise_to(state, target):
    target = max(int(target), state["min_raise_to"])
    if target >= state["your_stack"] + state["your_bet_this_street"]:
        return {"action": "all_in"}
    return {"action": "raise", "amount": target}


def decide(state):
    if state.get("type") == "warmup":
        eval7.evaluate([eval7.Card(c) for c in ("As", "Kd", "2c", "7h", "9s")])
        return {"action": "check"}
    P = prm(state)
    owed, pot, bb = state["amount_owed"], state["pot"], state["blinds"]["bb"]
    can_check = state["can_check"]
    hole, board = state["your_cards"], state["community_cards"]
    stack = state["your_stack"]
    r = random.random

    if P["always_fold"]:
        return {"action": "check"} if can_check else {"action": "fold"}
    if P["always_shove"]:
        return {"action": "all_in"}
    if P["station"]:
        return {"action": "check"} if can_check else {"action": "call"}

    opp = opp_of(state)
    eff = min(stack + state["your_bet_this_street"], opp["stack"] + opp["bet_this_street"])
    eff_bb = eff / bb

    def bet_size():
        if P["min_raise_only"]:
            return state["min_raise_to"]
        f = random.choice(P["bet_frac"])
        return state["current_bet"] + max(bb, f * (pot + owed))

    if state["street"] == "preflop":
        pct = _PCT[cls_of(hole)]
        if cls_of(hole) in P["raise_classes"] and not P["shove_bb"]:
            return raise_to(state, bb * P["open_bb"] if state["current_bet"] <= bb else state["current_bet"] * P["threebet_mult"])
        facing_raise = state["current_bet"] > bb
        if P["nash"] and eff_bb <= 15:
            on_button = state["button_seat"] == state["seat_to_act"]
            if on_button and not facing_raise_pf(state):
                return {"action": "all_in"} if pct <= interp(NASH_PUSH, eff_bb) else (
                    {"action": "check"} if can_check else {"action": "fold"})
            if facing_raise_pf(state) or owed > 0:
                return {"action": "call"} if pct <= interp(NASH_CALL, eff_bb) else {"action": "fold"}
            return {"action": "check"}
        if P["shove_bb"] and eff_bb <= P["shove_bb"]:
            if facing_raise or owed > 0 and state["current_bet"] > bb:
                return {"action": "all_in"} if pct <= P["call_shove_pct"] else {"action": "fold"}
            return {"action": "all_in"} if pct <= P["shove_pct"] else (
                {"action": "check"} if can_check else {"action": "fold"})
        if facing_raise:
            if pct <= P["threebet"] or r() < P["pf_bluff"] * 0.5:
                tgt = state["current_bet"] * P["threebet_mult"]
                if P["min_raise_only"]:
                    tgt = state["min_raise_to"]
                return raise_to(state, tgt)
            if pct <= P["call_raise"] and owed <= max(stack * 0.5, 3 * bb):
                return {"action": "call"}
            return {"action": "fold"}
        # nobody has raised yet (we may owe the blind difference)
        if pct <= P["pfr"] or r() < P["pf_bluff"]:
            return raise_to(state, bb * P["open_bb"] if not P["min_raise_only"] else state["min_raise_to"])
        if pct <= P["vpip"] and P["limp"]:
            return {"action": "check"} if can_check else {"action": "call"}
        return {"action": "check"} if can_check else {"action": "fold"}

    s = post_strength(hole, board)
    if can_check:
        if s >= 0.80 and r() < P["trap"]:
            return {"action": "check"}
        if P["size_tell"] == "polar":
            if s >= P["value_min"] and r() < P["cbet"] or s < 0.3 and r() < P["bluff"]:
                return raise_to(state, 2.5 * pot)
            return {"action": "check"}
        if s >= P["value_min"] and r() < max(P["cbet"], 0.5):
            tgt = bet_size()
            if P["size_tell"] == "inverted":
                tgt = max(bb, 0.25 * pot)
            return raise_to(state, tgt)
        if s >= 0.3 and r() < P["cbet"] * 0.5 or s < 0.3 and r() < P["bluff"]:
            tgt = bet_size()
            if P["size_tell"] == "inverted":
                tgt = max(bb, 1.2 * pot)
            return raise_to(state, tgt)
        return {"action": "check"}

    frac = owed / max(1, pot - owed)
    if s >= P["raise_min"]:
        return raise_to(state, state["current_bet"] * P["raise_mult"]) if r() < 0.7 or P["trap"] else {"action": "call"}
    if s < 0.3 and r() < P["bluff_raise"]:
        return raise_to(state, state["current_bet"] * P["raise_mult"])
    if s >= P["call_min"] + P["size_sens"] * frac:
        return {"action": "call"}
    if state["street"] == "flop" and r() < P["float"]:
        return {"action": "call"}
    return {"action": "fold"}
